+    testWidgets('light theme renders the assistant shadow-card look and the light tool surface', (tester) async {
+      await tester.pumpWidget(themedWrap(tile(FaChatMessage(role: 'assistant', content: 'light hi')), light: true));
+      expect(find.text('light hi'), findsOneWidget);
+      expect(find.byType(FaAiAvatar), findsOneWidget);
+      await tester.pumpWidget(themedWrap(tile(FaChatMessage(role: 'tool', content: 'ok out', toolName: 'bash')), light: true));
+      expect(find.textContaining('ok out'), findsOneWidget);
+      expect(find.byIcon(Icons.check), findsOneWidget);
+    });
+    testWidgets('an empty assistant message renders as nothing', (tester) async {
+      await tester.pumpWidget(themedWrap(tile(FaChatMessage(role: 'assistant', content: ''))));
+      expect(find.byType(MarkdownBody), findsNothing);
+      expect(find.byType(FaAiAvatar), findsNothing);
+    });
+    testWidgets('a thinking message renders the reasoning row, not a bubble', (tester) async {
+      await tester.pumpWidget(themedWrap(tile(FaChatMessage(role: 'thinking', content: 'step one'))));
+      expect(find.textContaining('step one'), findsOneWidget);
+      expect(find.byType(MarkdownBody), findsNothing);
+    });
+    testWidgets('a widget-role message renders the host tile when a builder is wired, the system shell row when not', (tester) async {
+      await tester.pumpWidget(themedWrap(tile(FaChatMessage(role: 'widget', content: 'live chip'),
+        dynamicWidgetTileBuilder: (context, message) => const Text('HOST TILE'))));
+      expect(find.text('HOST TILE'), findsOneWidget);
+      expect(find.byIcon(Icons.keyboard_arrow_down), findsNothing);
+      await tester.pumpWidget(themedWrap(tile(FaChatMessage(role: 'widget', content: 'echo'))));
+      expect(find.text('HOST TILE'), findsNothing);
+      expect(find.byIcon(Icons.keyboard_arrow_down), findsNothing);
+      expect(find.textContaining('echo', findRichText: true), findsOneWidget);
+    });
+    testWidgets('compact mode right-aligns user bubbles and bottom-pads the rest', (tester) async {
+      for role in ['user','assistant','tool']:
+        pump themedWrap(tile(role 'body', compact: true));
+        if user: expect one Align with Alignment.centerRight; else expect Align findsNothing;
+    });
+    testWidgets('a system row with no content renders an empty row', (tester) async {
+      pump tile(role system, content '');
+      expect MarkdownBody findsNothing; keyboard_arrow_down findsNothing;
+    });
+  });
+}

